import math

print("decibels:")
for label, L1, L2 in [("ten times", 60, 70), ("from levels to a ratio", 60, 80), ("a quieter sound", 85, 80)]:
    ratio = 10 ** ((L2 - L1) / 10)
    print(f"  {label}: {L1} dB to {L2} dB, ratio 10^({L2 - L1}/10) = {ratio:.4f}")
for k in [1, 2, 10]:
    print(f"  k = {k} equal sources of 70 dB: 70 + 10 log {k} = {70 + 10 * math.log10(k):.2f} dB")

print("pH:")
for label, h in [("lemon juice", 10 ** -2), ("coffee", 10 ** -5), ("between whole numbers", 4 * 10 ** -7)]:
    print(f"  {label}: [H+] = {h:.1e}, pH = -log [H+] = {-math.log10(h):.2f}")

print("earthquakes:")
for m1, m2 in [(5, 7), (4.5, 6.5)]:
    print(f"  magnitude {m2} against {m1}: amplitude x{10 ** (m2 - m1):g}, energy x{10 ** (1.5 * (m2 - m1)):.0f}")
